parameters.jsCode:
// Plan requests
// One item per HTTP request of this run. Bodies are built here, so a single
// HTTP node sends all of them (form bodies for URLhaus / MalwareBazaar, JSON
// for ThreatFox, GET for urlscan.io). Values come from sandbox traffic
// (attacker controlled): they are only ever sent as encoded parameters.
// Mode: Run Once for All Items.

const rows = $('Claim checks').all().map((i) => i.json).filter((r) => r.id);
const form = (o) => Object.entries(o).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
// No URL class in the Code node sandbox: take the host with a pattern.
const hostOf = (u) => { const m = /^https?:\/\/(?:[^@\/?#]*@)?([^:\/?#]+)/i.exec(String(u || '')); return m ? m[1].toLowerCase() : null; };
const reqs = [];
const add = (r, provider, endpoint, method, url, body, contentType, auth) =>
  reqs.push({ observable_id: r.id, kind: r.kind, value: r.value, provider, endpoint, method, url,
              body: body ?? '', content_type: method === 'GET' ? 'text/plain' : (contentType ?? 'application/json'), auth });

const TF = 'https://threatfox-api.abuse.ch/api/v1/';
const UH = 'https://urlhaus-api.abuse.ch/v1/';
const MB = 'https://mb-api.abuse.ch/api/v1/';
const FORM = 'application/x-www-form-urlencoded';

for (const r of rows) {
  if (r.abuse_due) {
    if (r.kind === 'host' || r.kind === 'ip') {
      add(r, 'threatfox', 'search_ioc', 'POST', TF, JSON.stringify({ query: 'search_ioc', search_term: r.value, exact_match: true }), null, 'abuse');
      add(r, 'urlhaus', 'host', 'POST', `${UH}host/`, form({ host: r.value }), FORM, 'abuse');
    } else if (r.kind === 'url') {
      add(r, 'urlhaus', 'url', 'POST', `${UH}url/`, form({ url: r.value }), FORM, 'abuse');
    } else if (r.kind === 'sha256') {
      add(r, 'malwarebazaar', 'get_info', 'POST', MB, form({ query: 'get_info', hash: r.value }), FORM, 'abuse');
      add(r, 'threatfox', 'search_hash', 'POST', TF, JSON.stringify({ query: 'search_hash', hash: r.value }), null, 'abuse');
    }
  }
  if (r.urlscan_result_due && r.urlscan_uuid) {
    add(r, 'urlscan', 'result', 'GET', `https://urlscan.io/api/v1/result/${encodeURIComponent(r.urlscan_uuid)}/`, '', null, 'urlscan');
  } else if (r.urlscan_wanted) {
    const host = hostOf(r.value);
    if (host) {
      const q = `page.domain:"${host.replace(/[^a-z0-9._-]/g, '')}" AND date:>now-7d`;
      add(r, 'urlscan', 'search', 'GET', `https://urlscan.io/api/v1/search/?size=5&q=${encodeURIComponent(q)}`, '', null, 'urlscan');
    }
  }
}
return reqs.map((json) => ({ json }));

// Evaluate results
// Turns every response into a check row for record_checks() and decides
// which top-level pages get a private urlscan.io scan (search found
// nothing, daily cap not reached). Response text is attacker-influenced:
// only short, length-capped fields are kept.
// Mode: Run Once for All Items.

const plan = $('Plan requests').all().map((i) => i.json);
const resp = $input.all().map((i) => i.json);
const rows = $('Claim checks').all().map((i) => i.json).filter((r) => r.id);
let scansLeft = rows.length ? Number(rows[0].urlscan_scans_left) || 0 : 0;

const cut = (s, n = 200) => (s == null ? null : String(s).replace(/\s+/g, ' ').trim().slice(0, n));
const parse = (b) => { if (typeof b !== 'string') return b || {}; try { return JSON.parse(b); } catch (e) { return { _text: b.slice(0, 200) }; } };
const results = new Map(rows.map((r) => [r.id, { observable_id: r.id, checks: [], abuse_checked: Boolean(r.abuse_due), urlscan: null }]));
const calls = [];
const submits = [];

function interpret(p, status, body) {
  const base = { provider: p.provider, http_status: status };
  if (status === null) return { ...base, outcome: 'error', summary: 'no response' };
  if (p.provider === 'urlscan') {
    if (p.endpoint === 'search') {
      if (status !== 200) return { ...base, outcome: 'error', summary: cut(body.message || body.description || `HTTP ${status}`) };
      const hits = Array.isArray(body.results) ? body.results : [];
      if (!hits.length) return { ...base, outcome: 'no_hit', summary: 'no earlier scan', _empty: true };
      const r = hits[0];
      const mal = r.verdicts?.overall?.malicious === true || r.verdicts?.malicious === true;
      return { ...base, outcome: mal ? 'hit' : 'no_hit', report_url: r.task?.uuid ? `https://urlscan.io/result/${r.task.uuid}/` : null,
               summary: cut(`earlier scan ${r.task?.time || ''}: ${r.page?.title || r.page?.url || ''}${mal ? ' — malicious' : ''}`),
               details: { uuid: r.task?.uuid || null, time: r.task?.time || null, page_url: cut(r.page?.url, 300), malicious: mal },
               _state: 'found' };
    }
    // result of our private scan
    if (status === 404) return { _pending: true };
    if (status !== 200) return { ...base, outcome: 'error', summary: cut(body.message || `HTTP ${status}`), _state: 'failed' };
    const v = body.verdicts?.overall || {};
    const mal = v.malicious === true;
    return { ...base, outcome: mal ? 'hit' : 'no_hit', report_url: `https://urlscan.io/result/${body.task?.uuid || ''}/`,
             summary: cut(`private scan: ${body.page?.title || body.page?.url || ''} — score ${v.score ?? 'n/a'}${mal ? ', malicious' : ''}`),
             details: { score: v.score ?? null, malicious: mal, categories: (v.categories || []).slice(0, 10), brands: (v.brands || []).slice(0, 10).map((b) => cut(b?.name || b, 60)),
                        final_url: cut(body.page?.url, 300), ip: body.page?.ip || null, country: body.page?.country || null },
             _state: 'done' };
  }
  if (status !== 200) return { ...base, outcome: 'error', summary: cut(body.message || body.query_status || `HTTP ${status}`) };
  const qs = body.query_status;
  if (p.provider === 'threatfox') {
    if (qs === 'no_result' || qs === 'no_results') return { ...base, outcome: 'no_hit' };
    if (qs !== 'ok' || !Array.isArray(body.data)) return { ...base, outcome: 'error', summary: cut(qs || body._text) };
    const d = body.data[0] || {};
    return { ...base, outcome: 'hit', report_url: d.id ? `https://threatfox.abuse.ch/ioc/${d.id}/` : null,
             summary: cut(`${d.malware_printable || d.malware || 'IOC'} (${d.threat_type || 'n/a'}, confidence ${d.confidence_level ?? 'n/a'}), ${body.data.length} IOC(s)`),
             details: { iocs: body.data.slice(0, 5).map((x) => ({ id: x.id, ioc: cut(x.ioc, 200), threat_type: x.threat_type, malware: cut(x.malware_printable, 80),
                                                                 confidence: x.confidence_level, first_seen: x.first_seen, last_seen: x.last_seen, tags: (x.tags || []).slice(0, 10) })) } };
  }
  if (p.provider === 'urlhaus') {
    if (qs === 'no_results' || qs === 'invalid_url' || qs === 'invalid_host') return { ...base, outcome: 'no_hit', summary: qs === 'no_results' ? null : qs };
    if (qs !== 'ok') return { ...base, outcome: 'error', summary: cut(qs || body._text) };
    if (p.endpoint === 'host') {
      const n = Number(body.url_count) || (Array.isArray(body.urls) ? body.urls.length : 0);
      return { ...base, outcome: n > 0 ? 'hit' : 'no_hit', report_url: body.urlhaus_reference || null,
               summary: cut(`${n} malware URL(s) on URLhaus${body.blacklists ? `, blacklists: ${Object.entries(body.blacklists).map(([k, v]) => `${k}=${v}`).join(' ')}` : ''}`),
               details: { url_count: n, urls: (body.urls || []).slice(0, 5).map((u) => ({ url: cut(u.url, 300), status: u.url_status, threat: u.threat, date_added: u.date_added, tags: (u.tags || []).slice(0, 10) })) } };
    }
    return { ...base, outcome: 'hit', report_url: body.urlhaus_reference || null,
             summary: cut(`URLhaus: ${body.threat || 'malware'} (${body.url_status || 'n/a'})${(body.tags || []).length ? `, tags ${body.tags.slice(0, 5).join(' ')}` : ''}`),
             details: { threat: body.threat, url_status: body.url_status, date_added: body.date_added, tags: (body.tags || []).slice(0, 10),
                        payloads: (body.payloads || []).slice(0, 5).map((x) => ({ sha256: x.response_sha256, file_type: x.file_type, signature: x.signature })) } };
  }
  if (p.provider === 'malwarebazaar') {
    if (qs === 'hash_not_found' || qs === 'no_results') return { ...base, outcome: 'no_hit' };
    if (qs !== 'ok' || !Array.isArray(body.data)) return { ...base, outcome: 'error', summary: cut(qs || body._text) };
    const d = body.data[0] || {};
    return { ...base, outcome: 'hit', report_url: `https://bazaar.abuse.ch/sample/${p.value}/`,
             summary: cut(`MalwareBazaar: ${d.signature || 'sample'} (${d.file_type || 'n/a'}), first seen ${d.first_seen || 'n/a'}`),
             details: { signature: d.signature, file_type: d.file_type, file_name: cut(d.file_name, 200), first_seen: d.first_seen, tags: (d.tags || []).slice(0, 10) } };
  }
  return { ...base, outcome: 'error', summary: 'unknown provider' };
}

plan.forEach((p, i) => {
  const res = resp[i] || {};
  const status = Number.isInteger(Number(res.statusCode)) && res.statusCode !== undefined ? Number(res.statusCode) : null;
  const body = parse(res.body);
  calls.push({ provider: p.provider === 'urlscan' ? 'urlscan' : 'abusech', caller: 'sandbox',
               endpoint: `${p.provider === 'urlscan' ? '' : `${p.provider}_`}${p.endpoint}`.slice(0, 40), http_status: status,
               message: res.error ? cut(res.error.message || res.error, 300) : null,
               fqdn: p.kind === 'host' ? p.value : null, observable_ip: p.kind === 'ip' ? p.value : null });
  const out = results.get(p.observable_id);
  if (!out) return;
  const c = interpret(p, status, body);
  if (c._pending) {
    // Scan not finished yet: try again next run; give up after 15 minutes.
    const row = rows.find((r) => r.id === p.observable_id);
    const age = row?.urlscan_submitted_at ? (Date.now() - Date.parse(row.urlscan_submitted_at)) / 60000 : 0;
    if (age > 15) {
      out.checks.push({ provider: 'urlscan', outcome: 'error', http_status: status, summary: 'private scan result not available after 15 minutes' });
      out.urlscan = { state: 'failed' };
    }
    return;
  }
  if (c._empty) {
    const row = rows.find((r) => r.id === p.observable_id);
    if (scansLeft > 0) {
      scansLeft -= 1;
      submits.push({ observable_id: p.observable_id, url: row.value });
      return;      // the submission's own result row is written by "Evaluate submits"
    }
    c.outcome = 'error';
    c.summary = 'no earlier scan; daily private scan limit reached';
  }
  if (c._state) out.urlscan = { state: c._state, uuid: c.details?.uuid || null };
  delete c._state; delete c._empty;
  out.checks.push(c);
});

return [{ json: { results: [...results.values()], calls, submits } }];

