-- Check rows + verdicts; returns the observables that became a hit and
-- were not e-mailed yet (only when sandbox_alert_enabled = 1).
SELECT * FROM cyber_sentinel_sandbox.record_checks($1::jsonb);

parameters.jsCode:
// Plan submits
// Top-level pages without an earlier urlscan.io scan: one item per private
// scan. No item = nothing to submit, this branch ends here.
// Mode: Run Once for All Items.

return $('Evaluate results').first().json.submits.map((json) => ({ json }));

// Evaluate submits
// Accepted scan -> urlscan_state 'submitted' + uuid; a later run fetches the
// result (claim_checks() returns it after a minute). Refused -> 'failed'.
// Mode: Run Once for All Items.

const plan = $('Plan submits').all().map((i) => i.json);
const resp = $input.all().map((i) => i.json);
const cut = (s, n = 200) => (s == null ? null : String(s).replace(/\s+/g, ' ').trim().slice(0, n));
const results = [];
const calls = [];
plan.forEach((p, i) => {
  const res = resp[i] || {};
  const status = Number.isInteger(Number(res.statusCode)) && res.statusCode !== undefined ? Number(res.statusCode) : null;
  let body = res.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { message: body.slice(0, 200) }; } }
  body = body || {};
  calls.push({ provider: 'urlscan', caller: 'sandbox', endpoint: 'scan', http_status: status,
               message: res.error ? cut(res.error.message || res.error, 300) : null });
  if (status === 200 && body.uuid) {
    results.push({ observable_id: p.observable_id, abuse_checked: false, urlscan: { state: 'submitted', uuid: body.uuid },
                   checks: [{ provider: 'urlscan', outcome: 'pending', http_status: status, summary: 'private scan submitted',
                              report_url: `https://urlscan.io/result/${body.uuid}/` }] });
  } else {
    results.push({ observable_id: p.observable_id, abuse_checked: false, urlscan: { state: 'failed' },
                   checks: [{ provider: 'urlscan', outcome: 'error', http_status: status,
                              summary: cut(`private scan refused: ${[body.message, body.description].filter(Boolean).join(' - ') || `HTTP ${status}`}`) }] });
  }
});
return [{ json: { results, calls } }];

// Build e-mail
// One e-mail for every sandbox observable that became a hit in this run.
// Everything is untrusted (it comes from the browsed site and from CTI
// feeds): HTML-escaped, URLs defanged.
// Mode: Run Once for All Items.

const hits = $('Store results').all().map((i) => i.json).filter((h) => h.id);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const defang = (s) => String(s ?? '').replace(/^http/i, 'hxxp').replace(/\./g, '[.]');
const rows = hits.map((h) => `<tr>
  <td style="padding:6px;border-bottom:1px solid #444">${esc(h.kind)}</td>
  <td style="padding:6px;border-bottom:1px solid #444;word-break:break-all"><code>${esc(defang(h.value).slice(0, 300))}</code>
    ${h.example_url ? `<br><small>from ${esc(defang(h.example_url).slice(0, 200))}</small>` : ''}</td>
  <td style="padding:6px;border-bottom:1px solid #444">${esc((h.hit_providers || []).join(', '))}</td>
  <td style="padding:6px;border-bottom:1px solid #444">${(h.summaries || []).slice(0, 3).map(esc).join('<br>')}
    ${(h.report_urls || []).slice(0, 3).map((u) => `<br><small>${esc(defang(u))}</small>`).join('')}</td>
</tr>`).join('');
const html = `<div style="font-family:sans-serif;background:#1e1e1e;color:#eee;padding:16px">
<h2 style="color:#ff5252;margin-top:0">🧪 Browser sandbox — CTI hit${hits.length > 1 ? 's' : ''}</h2>
<p>Something opened in the sandbox matches a threat-intelligence source. Details: AI Config UI → Sandbox.</p>
<table style="border-collapse:collapse;width:100%;font-size:13px">
<tr><th align="left">Type</th><th align="left">Observable</th><th align="left">Providers</th><th align="left">Findings</th></tr>
${rows}</table>
<p style="color:#999;font-size:12px">URLs are defanged (hxxp, [.]). Do not open them outside the sandbox.</p></div>`;
return [{ json: { subject: `🧪 Sandbox: ${hits.length} CTI hit${hits.length > 1 ? 's' : ''} — ${hits[0].value.slice(0, 60).replace(/\./g, '[.]')}`, html } }];
